    fortiapi::Field<std::string> as;  // Router AS number, asplain/asdot/asdot+ format, 0 to disable BGP. Required.
    fortiapi::Field<std::string> router_id;  // Router ID.
    fortiapi::Field<std::uint32_t> keepalive_timer;  // Frequency to send keep alive requests.
    fortiapi::Field<std::uint32_t> holdtime_timer;  // Number of seconds to mark peer as dead.
    fortiapi::Field<std::string> always_compare_med;  // Enable/disable always compare MED.
    fortiapi::Field<std::string> bestpath_as_path_ignore;  // Enable/disable ignore AS path.
    fortiapi::Field<std::string> bestpath_cmp_confed_aspath;  // Enable/disable compare federation AS path length.
    fortiapi::Field<std::string> bestpath_cmp_routerid;  // Enable/disable compare router ID for identical EBGP paths.
    fortiapi::Field<std::string> bestpath_med_confed;  // Enable/disable compare MED among confederation paths.
    fortiapi::Field<std::string> bestpath_med_missing_as_worst;  // Enable/disable treat missing MED as least preferred.
    fortiapi::Field<std::string> client_to_client_reflection;  // Enable/disable client-to-client route reflection.
    fortiapi::Field<std::string> dampening;  // Enable/disable route-flap dampening.
    fortiapi::Field<std::string> deterministic_med;  // Enable/disable enforce deterministic comparison of MED.
    fortiapi::Field<std::string> ebgp_multipath;  // Enable/disable EBGP multi-path.
    fortiapi::Field<std::string> ibgp_multipath;  // Enable/disable IBGP multi-path.
    fortiapi::Field<std::string> enforce_first_as;  // Enable/disable enforce first AS for EBGP routes.
    fortiapi::Field<std::string> fast_external_failover;  // Enable/disable reset peer BGP session if link goes down.
    fortiapi::Field<std::string> log_neighbour_changes;  // Log BGP neighbor changes.
    fortiapi::Field<std::string> network_import_check;  // Enable/disable ensure BGP network route exists in IGP.
    fortiapi::Field<std::string> ignore_optional_capability;  // Do not send unknown optional capability notification message.
    fortiapi::Field<std::string> additional_path;  // Enable/disable selection of BGP IPv4 additional paths.
    fortiapi::Field<std::string> additional_path6;  // Enable/disable selection of BGP IPv6 additional paths.
    fortiapi::Field<std::string> additional_path_vpnv4;  // Enable/disable selection of BGP VPNv4 additional paths.
    fortiapi::Field<std::string> additional_path_vpnv6;  // Enable/disable selection of BGP VPNv6 additional paths.
    fortiapi::Field<std::string> multipath_recursive_distance;  // Enable/disable use of recursive distance to select multipath.
    fortiapi::Field<std::string> recursive_next_hop;  // Enable/disable recursive resolution of next-hop using BGP route.
    fortiapi::Field<std::string> recursive_inherit_priority;  // Enable/disable priority inheritance for recursive resolution.
    fortiapi::Field<std::string> tag_resolve_mode;  // Configure tag-match mode. Resolves BGP routes with other routes containing the same tag.
    fortiapi::Field<std::string> cluster_id;  // Route reflector cluster ID.
    fortiapi::Field<std::uint32_t> confederation_identifier;  // Confederation identifier.
    fortiapi::Field<std::vector<ConfederationPeersEntry>> confederation_peers;  // Confederation peers.
    fortiapi::Field<std::string> dampening_route_map;  // Criteria for dampening. References: router.route-map.name.
    fortiapi::Field<std::uint32_t> dampening_reachability_half_life;  // Reachability half-life time for penalty (min).
    fortiapi::Field<std::uint32_t> dampening_reuse;  // Threshold to reuse routes.
    fortiapi::Field<std::uint32_t> dampening_suppress;  // Threshold to suppress routes.
    fortiapi::Field<std::uint32_t> dampening_max_suppress_time;  // Maximum minutes a route can be suppressed.
    fortiapi::Field<std::uint32_t> dampening_unreachability_half_life;  // Unreachability half-life time for penalty (min).
    fortiapi::Field<std::uint32_t> default_local_preference;  // Default local preference.
    fortiapi::Field<std::uint32_t> scan_time;  // Background scanner interval (sec), 0 to disable it.
    fortiapi::Field<std::uint32_t> distance_external;  // Distance for routes external to the AS.
    fortiapi::Field<std::uint32_t> distance_internal;  // Distance for routes internal to the AS.
    fortiapi::Field<std::uint32_t> distance_local;  // Distance for routes local to the AS.
    fortiapi::Field<std::string> synchronization;  // Enable/disable only advertise routes from iBGP if routes present in an IGP.
    fortiapi::Field<std::string> graceful_restart;  // Enable/disable BGP graceful restart capabilities.
    fortiapi::Field<std::uint32_t> graceful_restart_time;  // Time needed for neighbors to restart (sec).
    fortiapi::Field<std::uint32_t> graceful_stalepath_time;  // Time to hold stale paths of restarting neighbor (sec).
    fortiapi::Field<std::uint32_t> graceful_update_delay;  // Route advertisement/selection delay after restart (sec).
    fortiapi::Field<std::string> graceful_end_on_timer;  // Enable/disable to exit graceful restart on timer only.
    fortiapi::Field<std::uint32_t> additional_path_select;  // Number of additional paths to be selected for each IPv4 NLRI.
