    fortiapi::Field<std::string> cross_family_conditional_adv;  // Enable/disable cross address family conditional advertisement.
    fortiapi::Field<std::vector<AggregateAddressEntry>> aggregate_address;  // BGP aggregate address table.
    fortiapi::Field<std::vector<AggregateAddress6Entry>> aggregate_address6;  // BGP IPv6 aggregate address table.
    fortiapi::Field<std::vector<NeighborEntry>> neighbor;  // BGP neighbor table.
