    fortiapi::Field<std::vector<NeighborRangeEntry>> neighbor_range;  // BGP neighbor range table.
    fortiapi::Field<std::vector<NeighborRange6Entry>> neighbor_range6;  // BGP IPv6 neighbor range table.
    fortiapi::Field<std::vector<NetworkEntry>> network;  // BGP network table.
    fortiapi::Field<std::vector<Network6Entry>> network6;  // BGP IPv6 network table.
    fortiapi::Field<std::vector<RedistributeEntry>> redistribute;  // BGP IPv4 redistribute table. Read-only.
    fortiapi::Field<std::vector<Redistribute6Entry>> redistribute6;  // BGP IPv6 redistribute table. Read-only.
    fortiapi::Field<std::vector<AdminDistanceEntry>> admin_distance;  // Administrative distance modifications.
    fortiapi::Field<std::vector<VrfEntry>> vrf;  // BGP VRF leaking table.
    fortiapi::Field<std::vector<Vrf6Entry>> vrf6;  // BGP IPv6 VRF leaking table.

